#!/usr/bin/env node
// Добавляет в проект tg-channel-manager страницу «Парсер».
// Запуск:  node add-parser.mjs [путь/к/проекту]      (по умолчанию — текущая папка)
// Скрипт идемпотентен: повторный запуск ничего не дублирует. Изменяемые файлы сохраняются как *.bak-parser.
import fs from 'node:fs';
import path from 'node:path';

const root = path.resolve(process.argv[2] || '.');
const dec = (s) => Buffer.from(s, 'base64').toString('utf8');
const p = (f) => path.join(root, f);
const log = (m) => console.log(m);

const NEW_FILES = {
  "server/express/parser.js": "",
  "server/express/routes/parser.js": "",
  "pages/parser.vue": ""
};
const SCHEMA_SQL = dec('');
const CSS = dec('');

function die(msg) {
  console.error('Ошибка: ' + msg);
  process.exit(1);
}
for (const f of ['server/express/app.js', 'server/express/schema.js', 'app.vue', 'assets/main.css']) {
  if (!fs.existsSync(p(f))) die(`не найден ${f} — укажите корень проекта: node add-parser.mjs /путь/к/проекту`);
}

function backup(file) {
  const bak = file + '.bak-parser';
  if (!fs.existsSync(bak)) fs.copyFileSync(file, bak);
}
function edit(rel, fn) {
  const file = p(rel);
  const before = fs.readFileSync(file, 'utf8');
  const after = fn(before);
  if (after === before) return log(`= ${rel}: уже применено`);
  if (after === null) die(`${rel}: не нашёл место для вставки, правьте вручную`);
  backup(file);
  fs.writeFileSync(file, after);
  log(`~ ${rel}: изменён`);
}

// 1. новые файлы
for (const [rel, b64] of Object.entries(NEW_FILES)) {
  const file = p(rel);
  fs.mkdirSync(path.dirname(file), { recursive: true });
  if (fs.existsSync(file)) {
    if (fs.readFileSync(file, 'utf8') === dec(b64)) { log(`= ${rel}: без изменений`); continue; }
    backup(file);
  }
  fs.writeFileSync(file, dec(b64));
  log(`+ ${rel}`);
}

// 2. схема БД (создаётся при старте приложения)
edit('server/express/schema.js', (s) => {
  if (s.includes('parser_sources')) return s;
  const i = s.lastIndexOf('`;');
  return i < 0 ? null : s.slice(0, i) + SCHEMA_SQL + s.slice(i);
});

// 3. подключение API
edit('server/express/app.js', (s) => {
  if (s.includes('/api/parser')) return s;
  const lines = s.split('\n');
  const lastImport = lines.map((l) => l.startsWith('import ')).lastIndexOf(true);
  const route = lines.findIndex((l) => /app\.use\('\/api',\s*\(_req, res\)/.test(l)); // обработчик 404 для /api
  if (lastImport < 0 || route < 0) return null;
  lines.splice(route, 0, "app.use('/api/parser', parser);");
  lines.splice(lastImport + 1, 0, "import parser from './routes/parser.js';");
  return lines.join('\n');
});

// 4. пункт меню
edit('app.vue', (s) => {
  if (s.includes('to="/parser"')) return s;
  const m = s.match(/^([ \t]*)<NuxtLink to="\/">[^<]*<\/NuxtLink>[ \t]*\r?\n/m);
  if (!m) return null;
  return s.replace(m[0], m[0] + `${m[1]}<NuxtLink to="/parser">Парсер</NuxtLink>\n`);
});

// 5. стили
edit('assets/main.css', (s) => (s.includes('.src-row') ? s : s.replace(/\n*$/, '\n') + CSS));

// 6. seed (необязательно): очищать новые таблицы вместе с остальными
if (fs.existsSync(p('scripts/seed.js'))) {
  edit('scripts/seed.js', (s) =>
    s.includes('parsed_posts') ? s : s.replace(/truncate (sessions, post_likes, channel_stats, )posts/, 'truncate $1parsed_posts, parser_sources, posts'),
  );
}

log('\nГотово. Дальше:');
log('  npm run build && pm2 restart tg-channel-manager     # продакшн (PM2)');
log('  npm run dev                                         # разработка');
log('Таблицы создадутся сами при старте (или: npm run migrate). Новых npm-зависимостей нет.');
